messages.content:
{
  "title": "functions.expression.BooleanInputSchema",
  "description": "Schema for a boolean input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the boolean.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.BooleanInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.InputSchema",
  "description": "Schema for validating Function input.\n\nDefines the expected structure and constraints for input data.\nUsed by remote Functions to document and validate their inputs.",
  "anyOf": [
    {
      "title": "AnyOf",
      "description": "A union of schemas - input must match at least one.",
      "$ref": "functions.expression.AnyOfInputSchema"
    },
    {
      "title": "Object",
      "description": "An object with named properties.",
      "$ref": "functions.expression.ObjectInputSchema"
    },
    {
      "title": "Array",
      "description": "An array of items.",
      "$ref": "functions.expression.ArrayInputSchema"
    },
    {
      "title": "String",
      "description": "A string value.",
      "$ref": "functions.expression.StringInputSchema"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "$ref": "functions.expression.IntegerInputSchema"
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "$ref": "functions.expression.NumberInputSchema"
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "$ref": "functions.expression.BooleanInputSchema"
    },
    {
      "title": "Image",
      "description": "An image (URL or base64).",
      "$ref": "functions.expression.ImageInputSchema"
    },
    {
      "title": "Audio",
      "description": "Audio content.",
      "$ref": "functions.expression.AudioInputSchema"
    },
    {
      "title": "Video",
      "description": "Video content.",
      "$ref": "functions.expression.VideoInputSchema"
    },
    {
      "title": "File",
      "description": "A file.",
      "$ref": "functions.expression.FileInputSchema"
    }
  ]
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.SimpleContentExpression",
  "description": "Expression variant of [`SimpleContent`] for dynamic content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part text content expressions.",
      "type": "array",
      "items": {
        "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
        "anyOf": [
          {
            "title": "Expression",
            "description": "An expression (JMESPath or Starlark) to evaluate.",
            "$ref": "functions.expression.Expression"
          },
          {
            "title": "Value",
            "description": "A literal value.",
            "$ref": "agent.completions.message.SimpleContentPartExpression"
          }
        ]
      }
    }
  ]
}

{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "title": "ImageUrl",
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "title": "InputAudio",
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "title": "InputVideo",
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "VideoUrl",
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "File",
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.SystemMessageExpression",
  "description": "Expression variant of [`SystemMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.\n\nA value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "$ref": "agent.completions.message.SimpleContentExpression"
        }
      ]
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
          "anyOf": [
            {
              "title": "Expression",
              "description": "An expression (JMESPath or Starlark) to evaluate.",
              "$ref": "functions.expression.Expression"
            },
            {
              "title": "Value",
              "description": "A literal value.",
              "type": "string"
            }
          ]
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}
